// Package toml decodes TOML v1.0.0 documents using only the standard library.
package toml

import (
	"errors"
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// ErrSyntax reports a document that TOML v1.0.0 does not allow. Callers inspect
// it with errors.Is; the wrapped message names the line that failed.
var ErrSyntax = errors.New("invalid TOML")

// Decode reads a TOML document from r and returns its tagged-value model.
// Each top-level key maps to {"type", "value"} with the value as a string.
// Only top-level key/value pairs with string, boolean, integer, or float values are decoded so far.
func Decode(r io.Reader) (map[string]any, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("read document: %w", err)
	}
	if !utf8.Valid(data) {
		return nil, fmt.Errorf("%w: document is not valid UTF-8", ErrSyntax)
	}
	p := &parser{src: string(data)}
	doc, err := p.document()
	if err != nil {
		return nil, err
	}
	return doc.export(), nil
}

// parser scans src by byte offset. Multi-byte runes are copied through unchanged,
// so the ASCII delimiters the scanner checks are never confused with them.
type parser struct {
	src string
	pos int
}

func (p *parser) document() (table, error) {
	doc := table{}
	for {
		p.skipSpaces()
		if p.done() {
			return doc, nil
		}
		if c := p.src[p.pos]; c == '#' || c == '\n' || c == '\r' {
			if err := p.endOfLine(); err != nil {
				return nil, err
			}
			continue
		}
		parts, value, err := p.keyValue()
		if err != nil {
			return nil, err
		}
		if err := p.insert(doc, parts, value); err != nil {
			return nil, err
		}
		if err := p.endOfLine(); err != nil {
			return nil, err
		}
	}
}

func (p *parser) keyValue() ([]string, map[string]any, error) {
	parts, err := p.key()
	if err != nil {
		return nil, nil, err
	}
	name := strings.Join(parts, ".")
	p.skipSpaces()
	if p.done() || p.src[p.pos] != '=' {
		return nil, nil, p.errorf("expected '=' after key %q", name)
	}
	p.pos++
	p.skipSpaces()
	value, err := p.value()
	if err != nil {
		return nil, nil, err
	}
	return parts, value, nil
}

// value reads one value and returns its tagged model. Strings start with a quote;
// everything else is a bare boolean, integer, or float. The longer delimiters are
// tested first so that `"""` is never read as `""`.
func (p *parser) value() (map[string]any, error) {
	if p.done() {
		return nil, p.errorf("expected a value")
	}
	var s string
	var err error
	switch {
	case strings.HasPrefix(p.src[p.pos:], `"""`):
		s, err = p.multiline('"', true)
	case p.src[p.pos] == '"':
		s, err = p.basicString()
	case strings.HasPrefix(p.src[p.pos:], "'''"):
		s, err = p.multiline('\'', false)
	case p.src[p.pos] == '\'':
		s, err = p.literalString()
	default:
		return p.scalar()
	}
	if err != nil {
		return nil, err
	}
	return map[string]any{"type": "string", "value": s}, nil
}

// endOfLine consumes trailing spaces, an optional comment, and the line break.
// End of input also ends a line.
func (p *parser) endOfLine() error {
	p.skipSpaces()
	if !p.done() && p.src[p.pos] == '#' {
		p.pos++
		for !p.done() && !p.atNewline() {
			if isDisallowedControl(p.src[p.pos]) {
				return p.errorf("control character in comment")
			}
			p.pos++
		}
	}
	if p.done() {
		return nil
	}
	if p.src[p.pos] == '\n' {
		p.pos++
		return nil
	}
	if p.atCRLF() {
		p.pos += 2
		return nil
	}
	return p.errorf("unexpected text after value")
}

func (p *parser) skipSpaces() {
	for !p.done() && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
		p.pos++
	}
}

func (p *parser) done() bool {
	return p.pos >= len(p.src)
}

func (p *parser) atCRLF() bool {
	return strings.HasPrefix(p.src[p.pos:], "\r\n")
}

func (p *parser) atNewline() bool {
	return !p.done() && (p.src[p.pos] == '\n' || p.atCRLF())
}

func (p *parser) errorf(format string, args ...any) error {
	line := 1 + strings.Count(p.src[:p.pos], "\n")
	return fmt.Errorf("%w: line %d: %s", ErrSyntax, line, fmt.Sprintf(format, args...))
}

func isBareKeyByte(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
}

// isDisallowedControl reports whether c is a control character TOML forbids in
// strings and comments. Tab is the only control character it allows. Line breaks
// are excluded here because each caller decides whether a line break is legal.
func isDisallowedControl(c byte) bool {
	return (c < 0x20 && c != '\t' && c != '\n') || c == 0x7f
}
package toml

// table holds the entries of one TOML table while a document is read. A nested table
// is a table value; a key/value pair is the tagged map[string]any that value returns.
// The two dynamic types differ, so a table is never mistaken for a value.
type table map[string]any

// key reads a dotted key: one or more key parts joined by '.'. Spaces and tabs around
// each part are ignored. It returns the parts in order.
func (p *parser) key() ([]string, error) {
	var parts []string
	for {
		part, err := p.keyPart()
		if err != nil {
			return nil, err
		}
		parts = append(parts, part)
		p.skipSpaces()
		if p.done() || p.src[p.pos] != '.' {
			return parts, nil
		}
		p.pos++
		p.skipSpaces()
	}
}

// keyPart reads one bare key or one single-line quoted key. Table headers are not
// decoded yet, so a '[' is reported as a syntax error by the caller.
func (p *parser) keyPart() (string, error) {
	if p.done() {
		return "", p.errorf("expected a key")
	}
	switch p.src[p.pos] {
	case '"':
		return p.basicString()
	case '\'':
		return p.literalString()
	}
	start := p.pos
	for !p.done() && isBareKeyByte(p.src[p.pos]) {
		p.pos++
	}
	if p.pos == start {
		return "", p.errorf("expected a key")
	}
	return p.src[start:p.pos], nil
}

// insert stores value at the dotted path parts below doc, creating each intermediate
// table the path implies. A key may be defined once, and a key that holds a value
// cannot later be used as a table.
func (p *parser) insert(doc table, parts []string, value map[string]any) error {
	cur := doc
	for _, part := range parts[:len(parts)-1] {
		next, exists := cur[part]
		if !exists {
			sub := table{}
			cur[part] = sub
			cur = sub
			continue
		}
		sub, ok := next.(table)
		if !ok {
			return p.errorf("key %q holds a value and cannot be used as a table", part)
		}
		cur = sub
	}
	leaf := parts[len(parts)-1]
	if _, dup := cur[leaf]; dup {
		return p.errorf("duplicate key %q", leaf)
	}
	cur[leaf] = value
	return nil
}

// export converts the table tree to plain maps for the caller. Values are shared,
// not copied, because each leaf is already its final tagged form.
func (t table) export() map[string]any {
	out := make(map[string]any, len(t))
	for k, v := range t {
		if sub, ok := v.(table); ok {
			out[k] = sub.export()
			continue
		}
		out[k] = v
	}
	return out
}
// Command toml-decoder reads a TOML document on stdin and writes its
// tagged-JSON description to stdout. Diagnostics go to stderr and malformed
// input exits non-zero.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/owner/toml-decoder/internal/toml"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "toml-decoder:", err)
		os.Exit(1)
	}
}

// run decodes the document on in and encodes the result as JSON to out.
func run(in io.Reader, out io.Writer) error {
	doc, err := toml.Decode(in)
	if err != nil {
		return fmt.Errorf("decode: %w", err)
	}
	return json.NewEncoder(out).Encode(doc)
}

