package toml

// key reads a dotted key: one or more key parts joined by '.'. Spaces and tabs around
// each part are ignored. It returns the parts in order.
func (p *parser) key() ([]string, error) {
	var parts []string
	for {
		part, err := p.keyPart()
		if err != nil {
			return nil, err
		}
		parts = append(parts, part)
		p.skipSpaces()
		if p.done() || p.src[p.pos] != '.' {
			return parts, nil
		}
		p.pos++
		p.skipSpaces()
	}
}

// keyPart reads one bare key or one single-line quoted key. Table headers are not
// decoded yet, so a '[' is reported as a syntax error by the caller.
func (p *parser) keyPart() (string, error) {
	if p.done() {
		return "", p.errorf("expected a key")
	}
	switch p.src[p.pos] {
	case '"':
		return p.basicString()
	case '\'':
		return p.literalString()
	}
	start := p.pos
	for !p.done() && isBareKeyByte(p.src[p.pos]) {
		p.pos++
	}
	if p.pos == start {
		return "", p.errorf("expected a key")
	}
	return p.src[start:p.pos], nil
}

// insert stores value at the dotted path parts below doc, creating each intermediate
// table the path implies. A key may be defined once, and a key that holds a value
// cannot later be used as a table.
func (p *parser) insert(doc table, parts []string, value map[string]any) error {
	cur := doc
	for _, part := range parts[:len(parts)-1] {
		next, exists := cur[part]
		if !exists {
			sub := table{}
			cur[part] = sub
			cur = sub
			continue
		}
		sub, ok := next.(table)
		if !ok {
			return p.errorf("key %q holds a value and cannot be used as a table", part)
		}
		cur = sub
	}
	leaf := parts[len(parts)-1]
	if _, dup := cur[leaf]; dup {
		return p.errorf("duplicate key %q", leaf)
	}
	cur[leaf] = value
	return nil
}

// export converts the table tree to plain maps for the caller. Values are shared,
// not copied, because each leaf is already its final tagged form.
func (t table) export() map[string]any {
	out := make(map[string]any, len(t))
	for k, v := range t {
		if sub, ok := v.(table); ok {
			out[k] = sub.export()
			continue
		}
		out[k] = v
	}
	return out
}

